   _closed = False

   def close(self):
       """Close the file.

       After the file is closed, any other operation on it will
       raise a ValueError.
       """
       if self._closed:
           return
       self._closed = True

   @property
   def closed(self):
       """A boolean saying whether the file is closed."""
       return self._closed

   __del__ = close

   def __enter__(self):
       """Context management protocol.  Returns self."""
       if self._closed:
           raise ValueError("I/O operation on closed file")
       return self

   def __exit__(self, type, value, traceback):
       """Context management protocol.  Closes the file."""
       self.close()

